INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',82,'{"_type":"chat:Message","id":"8641420749:82","threadId":"telegram:8641420749","text":"And here is the list Pepe’s favourite that he shared with us. Save them with their original name, not the Spanish name. \n\nLista Mejores Películas Pepe Daroca\n\nOrden cronológico:\n\nMetrópolis. 1927. Fritz Lang \nTiempos modernos. 1936. Charles Chaplin \nEl gran dictador. 1940. Charles Chaplin \nCiudadano Kane. 1941. Orson Welles \nCasablanca. 1942. Michael Curtiz\nTo Be or Not To Be. 1942. Ernst Lubitsch\nQué bello es vivir. 1946. Frank Capra \nEl sueño eterno. 1946. Howards Hawks\nLadrón de bicicletas. 1948. Vittorio de Sica \nVacaciones en Roma. 1953. William Wyler \nCrimen perfecto. 1954. Alfred Hitchcock \nJohnny, Guitar. 1954. Nicolas Ray \nLa ventana indiscreta. 1954. Alfred Hitchcock\nRebelde sin causa. 1955. Nicolas Ray \nHorizontes de grandeza. 1958. William Wyler\nVértigo. 1958. Alfred Hitchcock\nCon la muerte en los talones. 1959. A. Hitchcock \nMi tío. 1958. Jacques Tati.\nBen-Hur. 1959. William Wyler\nDesayuno con diamantes. 1961. Blake Edwards\nMatar un ruiseñor. 1962. Robert Mulligan\nMuerte en Venecia. 1971. Luchino Visconti\nEl golpe. 1973. George Roy Hill\nEl amigo americano. 1977. Wim Wenders\nEl resplandor. 1980. Stanley Kubrick \nEl pianista. 2002. Roman Polanski \nMatch, Point. 2005. Woody Allen \nPozos de ambición. 2007. Paul Thomas Anderson.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"And here is the list Pepe’s favourite that he shared with us. Save them with their original name, not the Spanish name.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":120,"offset":119}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":121,"offset":120}}},{"type":"paragraph","children":[{"type":"text","value":"Lista Mejores Películas Pepe Daroca","position":{"start":{"line":3,"column":1,"off