INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',106,'{"_type":"chat:Message","id":"8641420749:172","threadId":"telegram:8641420749","text":"Notre employée Branca a commencé début janvier à travailler chez nous. Elle travaille tous les jours de la semaine, du lundi au vendredi, de 16h à 20h. Et deux jours par semaine elle reste jusqu''à 22h ou 23h pour faire du babysitting.\n\nElle nous aide principalement avec la maison, mais aussi avec les enfants quand ils rentrent de l''école. Donc c''est pour ça que normalement on n''a plus pris de babysitting pour des jours de semaine uniquement pour le week-end depuis janvier. Avant janvier on avait une employée qui venait le matin donc elle ne faisait pas du babysitting. Donc le babysitting couvrait la semaine et le week-end","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Notre employée Branca a commencé début janvier à travailler chez nous. Elle travaille tous les jours de la semaine, du lundi au vendredi, de 16h à 20h. Et deux jours par semaine elle reste jusqu''à 22h ou 23h pour faire du babysitting.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":235,"offset":234}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":235,"offset":234}}},{"type":"paragraph","children":[{"type":"text","value":"Elle nous aide principalement avec la maison, mais aussi avec les enfants quand ils rentrent de l''école. Donc c''est pour ça que normalement on n''a plus pris de babysitting pour des jours de semaine uniquement pour le week-end depuis janvier. Avant janvier on avait une employée qui venait le matin donc elle ne faisait pas du babysitting. Donc le babysitting couvrait la semaine et le week-end","position":{"start":{"line":3,"column":1,"offset":236},"end":{"line":3,"column":394,"offset":629}}}],"position":{"start":{"line":3,"column":1,"offset":236},"end":{"line":3,"column":394,"offset":629}}}],"position":{"start