INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',132,'{"_type":"chat:Message","id":"-5124234082:1572","threadId":"telegram:-5124234082","text":"Bonsoir Pépa,\n\nBranca a fait deux batches :\n- Un batch de légumes grillés au four : la moitié est au congélateur et l''autre moitié est dans le frigidaire.\n- Un batch de coleslaw qui est dans deux tupperwares au frigidaire\n\nCe soir on a mangé des wraps de merluza avec des légumes, comme tu nous avais donné la recette. On n''a plus de tortilla d''ailleurs. Faut en racheter, faut mettre sur la liste de course\n\nDonne moi le menu pour demain","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Bonsoir Pépa,","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":14,"offset":13}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":14,"offset":13}}},{"type":"paragraph","children":[{"type":"text","value":"Branca a fait deux batches :","position":{"start":{"line":3,"column":1,"offset":15},"end":{"line":3,"column":29,"offset":43}}}],"position":{"start":{"line":3,"column":1,"offset":15},"end":{"line":3,"column":29,"offset":43}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Un batch de légumes grillés au four : la moitié est au congélateur et l''autre moitié est dans le frigidaire.","position":{"start":{"line":4,"column":3,"offset":46},"end":{"line":4,"column":111,"offset":154}}}],"position":{"start":{"line":4,"column":3,"offset":46},"end":{"line":4,"column":111,"offset":154}}}],"position":{"start":{"line":4,"column":1,"offset":44},"end":{"line":4,"column":111,"offset":154}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Un batch de coleslaw qui est dans deux tupperwares au frigidaire","position":{"start":